<script>
  import { onMount } from 'svelte';
  import { webSocketStore } from '$lib/stores/websocket';
  import { filterStore } from '$lib/stores/filters';
  import MessageCard from './MessageCard.svelte';

  let filteredMessages = [];
  let wsState = null;
  let filterState = null;

  // Subscribe to stores
  $: if (webSocketStore && filterStore) {
    wsState = $webSocketStore;
    filterState = $filterStore;
  }

  // Filter messages based on current filter state
  $: if (wsState && filterState) {
    filteredMessages = wsState.messages.filter(message => {
      // Apply filters
      if (filterState.threatLevel && message.threatLevel !== filterState.threatLevel) {
        return false;
      }
      if (filterState.channel && message.channel !== filterState.channel) {
        return false;
      }
      if (filterState.minRelevance && message.relevanceScore < filterState.minRelevance) {
        return false;
      }
      return true;
    });
  }

  function handleMessageAction(event) {
    const { action, messageId } = event.detail;
    console.log(`Action: ${action} on message ${messageId}`);
    
    if (action === 'flag') {
      // Add visual feedback for flag action
      const messageElement = document.querySelector(`[data-message-id="${messageId}"]`);
      if (messageElement) {
        messageElement.style.backgroundColor = 'rgba(249, 115, 22, 0.1)';
        setTimeout(() => {
          messageElement.style.backgroundColor = '';
        }, 1000);
      }
    }
  }

  onMount(() => {
    // Initialize WebSocket connection
    webSocketStore.connect();
  });
</script>

<div class="telegram-feed">
  <div class="feed-header">
    <div class="feed-title">
      <h1>Live Intelligence Feed</h1>
      <div class="status-indicator {wsState?.connected ? 'active' : 'inactive'}">
        <div class="status-dot"></div>
        <span>{wsState?.connected ? 'LIVE MONITORING ACTIVE' : 'DISCONNECTED'}</span>
      </div>
    </div>
    <div class="feed-stats">
      <div class="stat">
        <span class="stat-value">{filteredMessages.length}</span>
        <span class="stat-label">Messages</span>
      </div>
      <div class="stat">
        <span class="stat-value">{wsState?.connected ? 'LIVE' : 'OFFLINE'}</span>
        <span class="stat-label">Status</span>
      </div>
    </div>
  </div>

  <div class="feed-content panel">
    {#if filteredMessages.length === 0}
      <div class="empty-state">
        <div class="empty-icon">📡</div>
        <h3>No messages match your filters</h3>
        <p>Adjust your filters or wait for new intelligence to arrive.</p>
      </div>
    {:else}
      <div class="message-list">
        {#each filteredMessages as message (message.id)}
          <div data-message-id={message.id}>
            <MessageCard {message} on:action={handleMessageAction} />
          </div>
        {/each}
      </div>
    {/if}
  </div>
</div>

